package net.officefloor.hq.app.sheet;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.TreeMap;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import org.springframework.context.annotation.Lazy;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Loads sheets by id; a sheet that was never loaded before starts empty. */
@Service
public class SheetService {

    /** The grades a person can have, each of which may have terms of its own. */
    private static final List<String> GRADES = List.of("A", "B", "C");

    private final SheetRepository sheets;
    private final SettingValueRepository settingValues;
    /** Lazy: the rollup reads the sheet's today through this service. */
    private final Rollup rollup;
    private final Audit audit;

    public SheetService(SheetRepository sheets, SettingValueRepository settingValues, @Lazy Rollup rollup, Audit audit) {
        this.sheets = sheets;
        this.settingValues = settingValues;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The sheet with this id, created empty the first time it is loaded, its today the real date. */
    @Transactional
    public synchronized Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> sheets.save(new Sheet(id, user, LocalDate.now())));
    }

    /** The sheet's today: the date every date-dependent decision and default date on it uses. */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElseGet(LocalDate::now);
    }

    /** The next claim number on the sheet: 1 for its first opened claim, then 2, and so on. */
    @Transactional
    public int nextClaimNumber(String id) {
        if (sheets.advanceClaimNumber(id) != 1) {
            throw new IllegalStateException("No sheet " + id);
        }
        return sheets.lastClaimNumber(id);
    }

    /** The next X-number on the sheet, for a claim in no period opened under period numbering: 1,
     *  then 2, and so on. */
    @Transactional
    public int nextUnperiodNumber(String id) {
        if (sheets.advanceUnperiodNumber(id) != 1) {
            throw new IllegalStateException("No sheet " + id);
        }
        return sheets.lastUnperiodNumber(id);
    }

    /** Change the sheet's today; the figures it moves are recorded, with no record of its own. */
    @Transactional
    public synchronized Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = load(id, user);
        return rollup.tracking(id, user, () -> {
            sheet.setToday(today);
            return sheets.saveAndFlush(sheet);
        });
    }

    /** The floor a sheet starts with, in force before every from-date of its own. */
    public static final BigDecimal STARTING_FLOOR = new BigDecimal("1.00");
    /** The late percent a sheet starts with, in force before every from-date of its own. */
    public static final BigDecimal STARTING_LATE_PCT = new BigDecimal("0.00");
    /** The terms a sheet starts with, in force before every from-date of its own. */
    public static final int STARTING_TERMS = 14;

    /** The value a dated setting of the sheet has recorded in force on a day: the one with the latest
     *  from-date on or before it; empty when none is (the value itself is null when blank). */
    private Optional<SettingValue> inForce(String id, String key, LocalDate day) {
        return settingValues.findFirstBySheetIdAndKeyAndFromLessThanEqualOrderByFromDesc(id, key, day);
    }

    /** The values recorded for a dated setting of the sheet, earliest from-date first. */
    @Transactional(readOnly = true)
    public List<SettingValue> recorded(String id, String key) {
        return settingValues.findBySheetIdAndKeyOrderByFrom(id, key);
    }

    /** Record a dated setting's value from a date (the sheet's today when none is given), keeping the
     *  values already recorded (one from the same date is replaced); recorded in the audit even when
     *  it is unchanged, with the from-date at the end when one was given. */
    private Sheet record(String id, String user, String key, BigDecimal value, String shown, LocalDate from) {
        Sheet sheet = load(id, user);
        LocalDate on = from != null ? from : sheet.getToday();
        SettingValue v = settingValues.findById(new SettingValue.Key(id, key, on))
                .orElseGet(() -> new SettingValue(id, key, on, value));
        v.setValue(value);
        settingValues.saveAndFlush(v);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=" + key + " value=" + shown
                + (from != null ? " from=" + from : ""));
        return sheet;
    }

    /** The most due a clerk may settle on a claim on the sheet: the limit in force on the sheet's
     *  today; null when there is no limit. */
    @Transactional(readOnly = true)
    public BigDecimal clerkLimit(String id) {
        return inForce(id, "clerk-limit", today(id)).map(SettingValue::getValue).orElse(null);
    }

    /** Record the sheet's clerk limit (null: no limit) from a date (null: the sheet's today). */
    @Transactional
    public synchronized Sheet setClerkLimit(String id, String user, BigDecimal limit, LocalDate from) {
        return record(id, user, "clerk-limit", limit, limit == null ? "" : limit.setScale(2).toPlainString(), from);
    }

    /** The least live due a claim on the sheet dated on the day has: the floor in force on it, or
     *  else the sheet's starting floor. */
    @Transactional(readOnly = true)
    public BigDecimal floor(String id, LocalDate day) {
        return inForce(id, "floor", day).map(SettingValue::getValue).orElse(STARTING_FLOOR);
    }

    /** The floor in force on the sheet's today. */
    @Transactional(readOnly = true)
    public BigDecimal floor(String id) {
        return floor(id, today(id));
    }

    /** Record the sheet's floor from a date (null: the sheet's today), then the figures it moves. */
    @Transactional
    public synchronized Sheet setFloor(String id, String user, BigDecimal floor, LocalDate from) {
        load(id, user);
        return rollup.tracking(id, user,
                () -> record(id, user, "floor", floor, floor.setScale(2).toPlainString(), from));
    }

    /** The days after its date a claim on the sheet dated on the day is due by: the sheet's terms in
     *  force on it, or else its starting terms. */
    @Transactional(readOnly = true)
    public int terms(String id, LocalDate day) {
        return inForce(id, "terms", day).map(v -> v.getValue().intValue()).orElse(STARTING_TERMS);
    }

    /** The sheet's terms in force on its today. */
    @Transactional(readOnly = true)
    public int terms(String id) {
        return terms(id, today(id));
    }

    /** Record the sheet's terms from a date (null: the sheet's today). They change no claim's due-by,
     *  which is fixed when the claim is made. */
    @Transactional
    public synchronized Sheet setTerms(String id, String user, int terms, LocalDate from) {
        load(id, user);
        return rollup.tracking(id, user,
                () -> record(id, user, "terms", BigDecimal.valueOf(terms), String.valueOf(terms), from));
    }

    /** The terms each grade on the sheet has of its own in force on its today, by grade; a grade not
     *  in it takes the sheet's terms. */
    @Transactional(readOnly = true)
    public Map<String, Integer> gradeTerms(String id) {
        LocalDate today = today(id);
        Map<String, Integer> terms = new TreeMap<>();
        for (String grade : GRADES) {
            inForce(id, "terms-" + grade, today).ifPresent(v -> terms.put(grade, v.getValue().intValue()));
        }
        return terms;
    }

    /** The terms in force on a day for a grade on the sheet: its own in force on the day, or else the
     *  sheet's. */
    @Transactional(readOnly = true)
    public int termsFor(String id, String grade, LocalDate day) {
        return inForce(id, "terms-" + grade, day).map(v -> v.getValue().intValue())
                .orElseGet(() -> terms(id, day));
    }

    /** Record a grade's own terms from a date (null: the sheet's today). They change no claim's
     *  due-by, which is fixed when the claim is made. */
    @Transactional
    public synchronized Sheet setGradeTerms(String id, String user, String grade, int terms, LocalDate from) {
        return record(id, user, "terms-" + grade, BigDecimal.valueOf(terms), String.valueOf(terms), from);
    }

    /** The percent of its figure an overdue claim on the sheet dated on the day gains for every full
     *  30 days it is overdue: the late percent in force on it, or else the sheet's starting one. */
    @Transactional(readOnly = true)
    public BigDecimal latePct(String id, LocalDate day) {
        return inForce(id, "late-pct", day).map(SettingValue::getValue).orElse(STARTING_LATE_PCT);
    }

    /** The late percent in force on the sheet's today. */
    @Transactional(readOnly = true)
    public BigDecimal latePct(String id) {
        return latePct(id, today(id));
    }

    /** Record the sheet's late percent from a date (null: the sheet's today), then the figures it
     *  moves. */
    @Transactional
    public synchronized Sheet setLatePct(String id, String user, BigDecimal latePct, LocalDate from) {
        load(id, user);
        return rollup.tracking(id, user,
                () -> record(id, user, "late-pct", latePct, latePct.setScale(2).toPlainString(), from));
    }

    /** The sheet's policy date as set; null when it is blank (the sheet's today then stands in). */
    @Transactional(readOnly = true)
    public LocalDate policyDate(String id) {
        return sheets.findById(id).map(Sheet::getPolicyDate).orElse(null);
    }

    /** The policy date in force: the one set, or else the sheet's today. */
    @Transactional(readOnly = true)
    public LocalDate policyDateInForce(String id) {
        return sheets.findById(id).map(s -> s.getPolicyDate() != null ? s.getPolicyDate() : s.getToday())
                .orElseGet(LocalDate::now);
    }

    /** Change the sheet's policy date (null: blank, the sheet's today); recorded even when it is
     *  unchanged, then the figures it moves. */
    @Transactional
    public synchronized Sheet setPolicyDate(String id, String user, LocalDate policyDate) {
        Sheet sheet = load(id, user);
        return rollup.tracking(id, user, () -> {
            sheet.setPolicyDate(policyDate);
            Sheet saved = sheets.saveAndFlush(sheet);
            audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=policy-date value="
                    + (policyDate == null ? "" : policyDate.toString()));
            return saved;
        });
    }

    /** The sheet's period numbering from date; null when it is blank (off). */
    @Transactional(readOnly = true)
    public LocalDate periodNumberingFrom(String id) {
        return sheets.findById(id).map(Sheet::getPeriodNumberingFrom).orElse(null);
    }

    /** Whether a claim opened on the sheet now is numbered within its period: the setting is a date
     *  and the sheet's today is on or after it. */
    @Transactional(readOnly = true)
    public boolean periodNumbering(String id) {
        return sheets.findById(id)
                .map(s -> s.getPeriodNumberingFrom() != null && !s.getToday().isBefore(s.getPeriodNumberingFrom()))
                .orElse(false);
    }

    /** Change the sheet's period numbering from date (null: blank, off); recorded even when it is
     *  unchanged. It changes no figure, and no number already given. */
    @Transactional
    public synchronized Sheet setPeriodNumberingFrom(String id, String user, LocalDate from) {
        Sheet sheet = load(id, user);
        sheet.setPeriodNumberingFrom(from);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=period-numbering-from value="
                + (from == null ? "" : from.toString()));
        return saved;
    }

    /** The most a person's due-total on the sheet comes to: the cap in force on the sheet's today;
     *  null when there is no cap. */
    @Transactional(readOnly = true)
    public BigDecimal cap(String id) {
        return inForce(id, "cap", today(id)).map(SettingValue::getValue).orElse(null);
    }

    /** Record the sheet's cap (null: no cap) from a date (null: the sheet's today), then the figures
     *  it moves. */
    @Transactional
    public synchronized Sheet setCap(String id, String user, BigDecimal cap, LocalDate from) {
        load(id, user);
        return rollup.tracking(id, user,
                () -> record(id, user, "cap", cap, cap == null ? "" : cap.setScale(2).toPlainString(), from));
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface SettingValueRepository extends JpaRepository<SettingValue, SettingValue.Key> {

    /** The value of a setting in force on a day: the one with the latest from-date on or before it. */
    Optional<SettingValue> findFirstBySheetIdAndKeyAndFromLessThanEqualOrderByFromDesc(String sheetId, String key,
            LocalDate day);

    /** The values recorded for a setting, earliest from-date first. */
    List<SettingValue> findBySheetIdAndKeyOrderByFrom(String sheetId, String key);
}
-- Dated settings: a figure a setting takes from a date on (the floor, the late percent, the terms of
-- the sheet and of each grade, the clerk limit and the cap). The value in force on a date is the one
-- with the latest from-date on or before it; before every from-date the sheet's starting value
-- (floor 1.00, late percent 0.00, terms 14; none for the others). A null value is blank (no limit,
-- no cap).
CREATE TABLE setting_value (
    sheet_id    VARCHAR(100)   NOT NULL,
    setting_key VARCHAR(20)    NOT NULL,
    from_date   DATE           NOT NULL,
    setting     DECIMAL(14, 2),
    PRIMARY KEY (sheet_id, setting_key, from_date)
);
-- The values already set carry over from the earliest date, so they stay in force everywhere.
INSERT INTO setting_value (sheet_id, setting_key, from_date, setting)
    SELECT id, 'floor', DATE '0001-01-01', due_floor FROM sheet WHERE due_floor <> 1.00;
INSERT INTO setting_value (sheet_id, setting_key, from_date, setting)
    SELECT id, 'late-pct', DATE '0001-01-01', late_pct FROM sheet WHERE late_pct <> 0.00;
INSERT INTO setting_value (sheet_id, setting_key, from_date, setting)
    SELECT id, 'terms', DATE '0001-01-01', terms FROM sheet WHERE terms <> 14;
INSERT INTO setting_value (sheet_id, setting_key, from_date, setting)
    SELECT id, 'clerk-limit', DATE '0001-01-01', clerk_limit FROM sheet WHERE clerk_limit IS NOT NULL;
INSERT INTO setting_value (sheet_id, setting_key, from_date, setting)
    SELECT id, 'cap', DATE '0001-01-01', cap FROM sheet WHERE cap IS NOT NULL;
INSERT INTO setting_value (sheet_id, setting_key, from_date, setting)
    SELECT sheet_id, 'terms-' || grade, DATE '0001-01-01', terms FROM grade_terms;
ALTER TABLE sheet DROP COLUMN due_floor;
ALTER TABLE sheet DROP COLUMN late_pct;
ALTER TABLE sheet DROP COLUMN terms;
ALTER TABLE sheet DROP COLUMN clerk_limit;
ALTER TABLE sheet DROP COLUMN cap;
DROP TABLE grade_terms;
-- The day an open claim is deferred until: until the sheet's today reaches it the claim counts in
-- no total, is not overdue, cannot be settled and a statement leaves it unbound. Null when never
-- deferred.
ALTER TABLE claim ADD COLUMN deferred_until DATE;

package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.role.SheetRole;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The claims people make on a sheet. */
@Service
public class ClaimService {

    private final ClaimRepository claims;
    private final PersonRepository people;
    private final Dues dues;
    private final SheetService sheets;
    private final Rollup rollup;
    private final PeriodRepository periods;
    private final RoleService roles;
    private final Audit audit;

    public ClaimService(ClaimRepository claims, PersonRepository people, Dues dues, SheetService sheets,
            Rollup rollup, PeriodRepository periods, RoleService roles, Audit audit) {
        this.claims = claims;
        this.people = people;
        this.dues = dues;
        this.sheets = sheets;
        this.rollup = rollup;
        this.periods = periods;
        this.roles = roles;
        this.audit = audit;
    }

    /** The claims on the sheet, newest first. */
    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByListedDesc(sheetId);
    }

    /** Add a claim for a person; a date left out takes the sheet's today. Refused when the date falls
     *  inside a closed period, or after the person's retirement day, and when a correction (a negative
     *  amount) does not name a settled claim of the person. */
    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
        return add(sheetId, user, personId, amount, date, note, null);
    }

    /** Add a claim for a person, naming the number of the claim it corrects (only a correction keeps it). */
    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        LocalDate on = date != null ? date : sheets.today(sheetId);
        refuseClosed(sheetId, on);
        refuseRetired(person(sheetId, personId), on);
        Claim corrected = corrected(sheetId, personId, amount, corrects);
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, personId);
            Claim draft = new Claim(sheetId, personId, amount, on, note,
                    corrected == null ? null : corrected.getNumber(), corrected == null ? null : corrected.getDate(),
                    on.plusDays(sheets.termsFor(sheetId, person.gradeOn(on), on)));
            logStatus(sheetId, user, person, draft);
            Claim claim = claims.saveAndFlush(draft);
            audit.recordOnCommit(record("CLAIM_ADDED", sheetId, user, person, claim));
            return claim;
        });
    }

    /** Change a draft claim's amount, date and note; a date left out takes the sheet's today. Refused
     *  when the claim is not a draft (an open claim is changed by voiding it and adding a new one), and
     *  when the claim's date, or the new one, falls inside a closed period, and when the new one is
     *  after the person's retirement day. */
    @Transactional
    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be edited");
        }
        LocalDate on = date != null ? date : sheets.today(sheetId);
        refuseClosed(sheetId, claim.getDate());
        refuseClosed(sheetId, on);
        refuseRetired(person(sheetId, claim.getPersonId()), on);
        Claim corrected = corrected(sheetId, claim.getPersonId(), amount, corrects);
        return rollup.tracking(sheetId, user, () -> {
            claim.setAmount(amount);
            claim.setCorrects(corrected == null ? null : corrected.getNumber());
            claim.setCorrectedDate(corrected == null ? null : corrected.getDate());
            claim.setDate(on);
            claim.setNote(note);
            Claim saved = claims.saveAndFlush(claim);
            audit.recordOnCommit(record("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved));
            return saved;
        });
    }

    /** Move a claim to a new status; a change its current status does not allow is refused, and so
     *  is settling a claim by the user who opened it, and any change to a claim dated inside a closed
     *  period. A clerk settling a claim whose due is above the sheet's clerk limit leaves it pending
     *  a steward's approval instead. */
    @Transactional
    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to) {
        Claim claim = lock(sheetId, claimId);
        refuseClosed(sheetId, claim.getDate());
        if (!claim.getStatus().canBecome(to) || to == ClaimStatus.PENDING) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot become " + to);
        }
        if (to == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then");
        }
        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "The user who opened a claim cannot settle it");
        }
        ClaimStatus becomes = to == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, claim)
                ? ClaimStatus.PENDING : to;
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, claim.getPersonId());
            if (becomes == ClaimStatus.SETTLED) {
                // Settling fixes the due at what it is now, while the claim is still open (the figure a
                // statement bound it to, if any, and its late charge); later changes to rates, the
                // late percent and the sheet's today do not alter it.
                claim.setSettledDue(dues.figure(sheetId, person, claim));
            }
            // A void claim keeps the number it had (never reused).
            claim.setStatus(becomes);
            if (becomes == ClaimStatus.OPEN) {
                claim.setNumber(nextNumber(sheetId, claim.getDate()));
                claim.setOpenedBy(user);
            }
            logStatus(sheetId, user, person, claim);
            Claim saved = claims.saveAndFlush(claim);
            String event = switch (becomes) {
                case OPEN -> "CLAIM_OPENED";
                case PENDING -> "CLAIM_PENDING";
                case SETTLED -> "CLAIM_SETTLED";
                case VOID -> "CLAIM_VOIDED";
                case DRAFT -> throw new IllegalStateException("a claim never returns to DRAFT");
            };
            String line = record(event, sheetId, user, person, saved);
            if (becomes == ClaimStatus.SETTLED) {
                line += " due=" + dueText(saved.getSettledDue());
            }
            audit.recordOnCommit(line);
            return saved;
        });
    }

    /** Defer an open claim until a day after the sheet's today: until the sheet's today reaches it,
     *  the claim counts in no total, is not overdue, cannot be settled and a statement leaves it
     *  unbound. Refused when the claim's period is closed, the claim is not open, or the day is not
     *  after the sheet's today. */
    @Transactional
    public Claim defer(String sheetId, String user, long claimId, LocalDate until) {
        Claim claim = lock(sheetId, claimId);
        refuseClosed(sheetId, claim.getDate());
        if (claim.getStatus() != ClaimStatus.OPEN) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be deferred");
        }
        if (!until.isAfter(sheets.today(sheetId))) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                    "A claim can only be deferred to a date after the sheet's today");
        }
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, claim.getPersonId());
            claim.deferUntil(until);
            Claim saved = claims.saveAndFlush(claim);
            audit.recordOnCommit(record("CLAIM_DEFERRED", sheetId, user, person, saved) + " until=" + until);
            return saved;
        });
    }

    /** Approve a pending claim: it becomes settled, its due fixed at the figure it has now (its live
     *  figure and late charge). Refused unless the claim is pending, the user is a steward and is not
     *  the one who opened it, and the claim's period is open. */
    @Transactional
    public Claim approve(String sheetId, String user, long claimId) {
        Claim claim = lockPending(sheetId, user, claimId);
        if (user.equals(claim.getOpenedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "The user who opened a claim cannot approve it");
        }
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, claim.getPersonId());
            claim.setSettledDue(dues.figure(sheetId, person, claim));
            claim.setStatus(ClaimStatus.SETTLED);
            logStatus(sheetId, user, person, claim);
            Claim saved = claims.saveAndFlush(claim);
            audit.recordOnCommit(record("CLAIM_APPROVED", sheetId, user, person, saved)
                    + " due=" + dueText(saved.getSettledDue()));
            return saved;
        });
    }

    /** Re-settle a settled claim: its due is fixed again at the figure it would have today as an open
     *  claim bound by no statement (today's rates, grades, floor and late charge). Refused unless the
     *  claim is settled, the user is a steward, and the claim's period is open. */
    @Transactional
    public Claim resettle(String sheetId, String user, long claimId) {
        Claim claim = lock(sheetId, claimId);
        refuseClosed(sheetId, claim.getDate());
        if (claim.getStatus() != ClaimStatus.SETTLED) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a SETTLED claim can be re-settled");
        }
        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-settle a claim");
        }
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, claim.getPersonId());
            BigDecimal old = dues.figure(sheetId, person, claim);
            BigDecimal now = dues.openFigure(sheetId, person, claim);
            claim.setSettledDue(now);
            claim.logStatus(user, sheets.today(sheetId), now);
            Claim saved = claims.saveAndFlush(claim);
            audit.recordOnCommit(record("CLAIM_RESETTLED", sheetId, user, person, saved)
                    + " old=" + dueText(old) + " new=" + dueText(now));
            return saved;
        });
    }

    /** Reject a pending claim for a reason: it is open again, bound again by its person's last
     *  statement if that statement included it. Refused unless the claim is pending, the user is a
     *  steward, and the claim's period is open. */
    @Transactional
    public Claim reject(String sheetId, String user, long claimId, String reason) {
        Claim claim = lockPending(sheetId, user, claimId);
        return rollup.tracking(sheetId, user, () -> {
            Person person = person(sheetId, claim.getPersonId());
            claim.setStatus(ClaimStatus.OPEN);
            logStatus(sheetId, user, person, claim);
            Claim saved = claims.saveAndFlush(claim);
            audit.recordOnCommit(record("CLAIM_REJECTED", sheetId, user, person, saved) + " reason=" + reason);
            return saved;
        });
    }

    /** Move a draft, open or pending claim to another person on the sheet. It keeps its number, date
     *  and status, loses any figure a statement bound it to, and is listed as its new person's newest
     *  claim. Refused unless the user is a steward, and when the claim is settled or void, the person
     *  is the one it is already for, the claim's period is closed, or the claim is dated after the
     *  new person's retirement day. */
    @Transactional
    public Claim reassign(String sheetId, String user, long claimId, long toPersonId) {
        Claim claim = lock(sheetId, claimId);
        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can reassign a claim");
        }
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be reassigned");
        }
        if (claim.getPersonId() == toPersonId) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The claim is already that person's");
        }
        refuseClosed(sheetId, claim.getDate());
        Person from = person(sheetId, claim.getPersonId());
        Person to = person(sheetId, toPersonId);
        refuseRetired(to, claim.getDate());
        return rollup.tracking(sheetId, user, () -> {
            claim.moveTo(to.getId(), claims.nextListed());
            Claim saved = claims.saveAndFlush(claim);
            audit.recordOnCommit(record("CLAIM_REASSIGNED", sheetId, user, to, saved)
                    + " from=" + from.getName() + " to=" + to.getName());
            return saved;
        });
    }

    /** The pending claim a steward approves or rejects, locked; refused when it is not pending, the
     *  user is not a steward, or its period is closed. */
    private Claim lockPending(String sheetId, String user, long claimId) {
        Claim claim = lock(sheetId, claimId);
        refuseClosed(sheetId, claim.getDate());
        if (claim.getStatus() != ClaimStatus.PENDING) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "Only a PENDING claim can be approved or rejected");
        }
        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "Only a steward can approve or reject a claim");
        }
        return claim;
    }

    /** Log the status the claim has now, changed by the user on the sheet's today, with its due as
     *  computed at this moment. */
    private void logStatus(String sheetId, String user, Person person, Claim claim) {
        claim.logStatus(user, sheets.today(sheetId), dues.figure(sheetId, person, claim));
    }

    private Claim lock(String sheetId, long claimId) {
        return claims.lockByIdAndSheetId(claimId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
    }

    private static String dueText(BigDecimal due) {
        return due == null ? "n/a" : due.setScale(2).toPlainString();
    }

    /** The number for a claim of the date opened now: under period numbering, the next in its period
     *  (<period name>-<n>), or for one in no period the next X-<n>; otherwise the next on the sheet. */
    private String nextNumber(String sheetId, LocalDate date) {
        if (!sheets.periodNumbering(sheetId)) {
            return String.valueOf(sheets.nextClaimNumber(sheetId));
        }
        return periods.findOn(sheetId, date)
                .map(p -> {
                    periods.advanceClaimNumber(p.getId());
                    return p.getName() + "-" + periods.lastClaimNumber(p.getId());
                })
                .orElseGet(() -> "X-" + sheets.nextUnperiodNumber(sheetId));
    }

    /** The claim a claim of the amount corrects: none for an amount of 0.00 or more; for a correction
     *  (a negative amount), the one of the number given, which must be a settled claim of the person,
     *  or else it is refused. */
    private Claim corrected(String sheetId, long personId, BigDecimal amount, String corrects) {
        if (amount.signum() >= 0) {
            return null;
        }
        return (corrects == null ? Optional.<Claim>empty()
                : claims.findBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,
                        "A negative amount must correct a settled claim of the same person"));
    }

    /** Refuse a change to a claim dated on the day when the day falls inside a closed period. */
    private void refuseClosed(String sheetId, LocalDate day) {
        if (periods.closedOn(sheetId, day)) {
            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's period is closed");
        }
    }

    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit in force on its today; a claim with
     *  no due (n/a) is within any limit, and a steward settles anything. */
    private boolean overClerkLimit(String sheetId, String user, Claim claim) {
        BigDecimal limit = sheets.clerkLimit(sheetId);
        if (limit == null || SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
            return false;
        }
        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
        return due != null && due.compareTo(limit) > 0;
    }

    /** Refuse a claim of the person dated after the day they are retired from. */
    private static void refuseRetired(Person person, LocalDate day) {
        if (person.getRetiredFrom() != null && day.isAfter(person.getRetiredFrom())) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                    "A claim cannot be dated after the person's retirement");
        }
    }

    private Person person(String sheetId, long personId) {
        return people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
    }

    /** An audit record about a claim; one that has a number carries it at the end. */
    private static String record(String event, String sheetId, String user, Person person, Claim claim) {
        String number = claim.getNumber();
        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
                + (number != null ? " number=" + number : "");
    }
}
